// This file was generated by Prisma and assumes you have installed the following:
// npm install --save-dev prisma dotenv
import "dotenv/config";
import { defineConfig } from "prisma/config";

// `prisma generate` (postinstall) no necesita conectarse a la base. Con
// env("DATABASE_URL") el config truena si la variable no existe, y eso rompía
// los builds de Preview en Vercel, donde no está definida. Solo los comandos
// que sí usan la base (migrate, db push, studio) la necesitan.
const url = process.env.DATABASE_URL || process.env.POSTGRES_PRISMA_URL;

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  engine: "classic",
  ...(url ? { datasource: { url } } : {}),
});
